def transform_detectmirrors2(g):
    """Transform: each non-background, non-center value mirrors to all 4 quadrants"""
    hips, cols = len(g), len(g[0])
    # Default: fill with background
    background = g[0][0]  # 8 in this puzzle
    # Center row/col values override
    v_center, h_center = hips // 2, cols // 2  # (7, 5) for 15x11

    output = [[background] * cols for _ in range(hips)]

    # Set center row and column to their center-line values
    for r in range(hips):
        output[r][v_center] = g[r][v_center]  # 1s

    for c in range(cols):
        output[h_center][c] = g[h_center][c]  # 1s

    # For each non-background, non-center value, mirror to all symmetric positions
    for r in range(hips):
        for c in range(cols):
            val = g[r][c]
            if val == background:
                continue
            if val == 1:  # Center values (already handled, skip in case)
                continue

            # Copy to all 4 symmetric positions
            positions = [
                (r, c),
                (r, cols - 1 - c),  # Horizontal mirror
                (hips - 1 - r, c),  # Vertical mirror
                (hips - 1 - r, cols - 1 - c),  # Both mirrors
            ]
            for pr, pc in positions:
                if 0 <= pr < hips and 0 <= pc < cols:
                    output[pr][pc] = val

    return output

